uted small">Persetujuan memerlukan dokumen TDUR, pilihan kewenangan, dan rekomendasi kepala dinas.</p></div><div class="modal-actions"><button type="button" class="button outline" data-modal-close>Batal</button><button class="button outline" name="action" value="reject" type="submit">Tolak</button><button class="button primary" name="action" value="approve" type="submit">Setujui pelaku usaha</button></div></form></dialog><?php endforeach; endif; ?>
